function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function get(path){const response=await fetch(origin()+path,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());return response.json()}
async function run(input){if(input.confirm_python_execution!==true)throw new Error('Strategy preview requires explicit Python execution confirmation');const id=String(input.project_id||'').trim();if(!id)throw new Error('project_id is required');const base='/api/strategy/projects/'+encodeURIComponent(id);const project=await get(base);if(project.dirty)throw new Error('Save the project source before previewing it');const revision=Number(project.current_revision);const pkg=await get(base+'/revisions/'+revision);const response=await fetch(origin()+base+'/preview',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify({operation:input.operation,profile:'runtime',revision,...(input.as_of_date?{as_of_date:String(input.as_of_date)}:{}),confirm_python_execution:true})});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());const result=await response.json();if(result.revision!==revision||result.source_sha256!==pkg.source_sha256)throw new Error('Strategy source package changed during preview');return{...result,strategy_source_package:{project_id:id,revision,source_sha256:pkg.source_sha256}}}
